/**
 * Handles showing and hiding the BrightHire sidepanel across all Lever pages
 */
import { onSidepanelRemoved, setupDrawer } from "../../utils/drawer";
import { addPassiveMessageListener } from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { checkUrlMatches } from "../../utils/url";
import { leverUrlMap } from "../../utils/urlMapping";
import { waitForHydration } from "./utils";

const checkSidepanel = async (): Promise<void> => {
  const { pathname } = window.location;
  if (checkUrlMatches(pathname, leverUrlMap)) {
    if (pathname.startsWith("/interviews")) {
      await waitForHydration();
      onSidepanelRemoved().then(() => {
        setupDrawer();
      });
    }
    setupDrawer();
  }
};

onDocumentLoaded(() => {
  checkSidepanel();

  addPassiveMessageListener(({ message }) => {
    if (message.action === "tabUrlChanged") {
      checkSidepanel();
    }
  });
});
