import { captureException } from "./sentry";

export const sendMessage = async (
  message: Message,
): Promise<MessageResponse | undefined> => chrome.runtime.sendMessage(message);

export const getTabId = async (): Promise<number | undefined> => {
  const response = await sendMessage({ action: "getTabId" });
  return response?.tabId;
};

export const sendMessageWithTabId: typeof sendMessage = async (message) =>
  sendMessage({
    ...message,
    payload: {
      ...message.payload,
      tabId: await getTabId(),
    },
  });

export const sendGAEvent = (gaEvent: GAEvent): void => {
  sendMessageWithTabId({ action: "gaEvent", payload: { gaEvent } });
};

const isPromise = <T>(r: any): r is Promise<T> => r?.then !== undefined;

type AddMessageListenerParams = {
  passive?: boolean;
};

/**
 * Listens for messages from the background script / service worker or
 * other content scripts, and handles optionally returning a response,
 * synchronously or asynchronously.
 *
 * If no response is required, prefer `addPassiveMessageListener`
 *
 * See [chrome docs](https://developer.chrome.com/docs/extensions/develop/concepts/messaging#simple)
 * for a full breakdown of how message passing works.
 */
export const addMessageListener = (
  handler: MessageListener,
  params?: AddMessageListenerParams,
): void =>
  // biome-ignore lint/plugin: this file is the canonical wrapper for chrome.runtime.onMessage.
  chrome.runtime.onMessage.addListener(
    (
      message: Message,
      sender: chrome.runtime.MessageSender,
      // biome-ignore lint/suspicious/noConfusingVoidType: matches MessageListener return signature so handlers can be `() => void`
      sendResponse: (response: MessageResponse | void) => void,
    ) => {
      let response: ReturnType<MessageListener>;
      try {
        response = handler({ message, sender });
      } catch (err) {
        captureException(err);
        throw err;
      }

      if (params?.passive) return;

      /**
       *  Only the first call to `sendResponse` is respected, so we are
       *  only going to call it `response` is defined.
       *
       *  Otherwise, passive listeners will drown out the "real" response
       */
      const sendResponseIfTruthy: typeof sendResponse = (r) => {
        if (r || process.env.APP_ENV === "test") {
          sendResponse(r);
        }
      };

      /** If a response is to be returned asynchronously, this handler must return `true` */
      if (isPromise(response)) {
        response.then(sendResponseIfTruthy).catch((err) => {
          sendResponse(undefined);
          throw err;
        });
        return true;
      }

      sendResponseIfTruthy(response);
    },
  );

/**
 * Passively listens for messages from the background script / service worker
 * or other content scripts **without** the ability to return a response.
 */
export const addPassiveMessageListener = (handler: MessageListener): void =>
  addMessageListener(handler, { passive: true });

export const addMessageListenerExternal = (handler: MessageListener): void =>
  // biome-ignore lint/plugin: this file is the canonical wrapper for chrome.runtime.onMessageExternal.
  chrome.runtime.onMessageExternal.addListener(
    (
      message: Message,
      sender: chrome.runtime.MessageSender,
      // biome-ignore lint/suspicious/noConfusingVoidType: matches MessageListener return signature so handlers can be `() => void`
      sendResponse: (response: MessageResponse | void) => void,
    ) => {
      let response: ReturnType<MessageListener>;
      try {
        response = handler({ message, sender });
      } catch (err) {
        captureException(err);
        throw err;
      }

      if (isPromise(response)) {
        response.then(sendResponse);
        return true;
      }

      sendResponse(response);
    },
  );
