import { MutationSummary } from "../../utils/MutationSummary";

/**
 * Lever users a SSR framework that does not play well with extensions.
 * The client "hydrates" the SSR page, and if the DOM changes from
 * what the server sent during hydration you get an error like:
 *
 * ```
 * Error: Attaching bindings failed, because HTML structure does not match client rendering
 * ```
 *
 * Searching the web, it seems known that extensions don't work well with this,
 * but I was unable to find any workaround that extension developers could use.
 *
 * Our strategy is to wait for the first change reported by a `MutationSummary`
 * to indicate hydration is complete, with a fallback of waiting at most 1 second.
 */
export const waitForHydration = async (
  rootNode: Node = document.body,
): Promise<void> => {
  return new Promise((resolve) => {
    const fallback = setTimeout(resolve, 1000);
    const summary = new MutationSummary({
      rootNode,
      queries: [{ all: true }],
      callback: () => {
        resolve();
        clearTimeout(fallback);
        summary.disconnect();
      },
    });
  });
};
